#include <chrono>
#include <iostream>

// ① 抽象接口：被测代码只认识它，从不自己取系统时间
struct IClock {
    virtual ~IClock() = default;
    virtual long long now_ms() const = 0;
};

struct FakeClock : IClock {          // 假实现：时间完全由测试驱动
    long long t = 0;
    long long now_ms() const override { return t; }
    void advance(long long d) { t += d; }
};

struct SystemClock : IClock {        // 真实现：生产环境注入
    long long now_ms() const override {
        using namespace std::chrono;
        return duration_cast<milliseconds>(steady_clock::now().time_since_epoch()).count();
    }
};

// ② 依赖注入：RateLimiter 只持有引用
class RateLimiter {
public:
    RateLimiter(const IClock& clk, int capacity, long long window_ms)
        : clk_(clk), cap_(capacity), win_(window_ms) {}

    bool allow() {
        long long now = clk_.now_ms();
        if (start_ < 0 || now - start_ >= win_) { start_ = now; used_ = 0; }
        if (used_ < cap_) { ++used_; return true; }
        return false;
    }

private:
    const IClock& clk_;
    int cap_;
    long long win_;
    long long start_ = -1;
    int used_ = 0;
};

static const char* B(bool v) { return v ? "True" : "False"; }

int main() {
    FakeClock fake;                       // ③ 测试注入：无需 sleep，毫秒级、结果稳定
    RateLimiter rl(fake, 3, 1000);
    for (int i = 1; i <= 5; ++i)
        std::cout << "t=" << fake.now_ms() << " 第" << i << "次 allow=" << B(rl.allow()) << "\n";
    fake.advance(1000);                   // 一步跨到下一个窗口
    std::cout << "t=" << fake.now_ms() << " 第6次 allow=" << B(rl.allow()) << "\n";
    return 0;
}

