#include <iostream>
#include <vector>

// 二分查找：返回下标，不存在返回 -1（搜索区间为左闭右开 [lo, hi)）
int binary_search_idx(const std::vector<int>& a, int target) {
    int lo = 0, hi = static_cast<int>(a.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;          // 防溢出的取中点写法
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return (lo < static_cast<int>(a.size()) && a[lo] == target) ? lo : -1;
}

static int checks = 0, failed = 0;
static void eq(int got, int want, int line) {
    ++checks;
    if (got != want) {
        ++failed;
        std::cout << "[ ASSERT ] 第" << line << "行 期望=" << want << " 实得=" << got << "\n";
    }
}

int main() {
    std::vector<int> a = {1, 3, 5, 7, 9};
    // 边界值：首元素 / 末元素 / 小于最小 / 大于最大 / 中间不存在 / 空容器
    eq(binary_search_idx(a, 1), 0, __LINE__);
    eq(binary_search_idx(a, 9), 4, __LINE__);
    eq(binary_search_idx(a, 0), -1, __LINE__);
    eq(binary_search_idx(a, 10), -1, __LINE__);
    eq(binary_search_idx(a, 4), -1, __LINE__);
    std::vector<int> empty;
    eq(binary_search_idx(empty, 1), -1, __LINE__);
    std::cout << "[SUMMARY] 断言=" << checks << " 失败断言=" << failed << "\n";
    return failed ? 1 : 0;
}

#include <iostream>
#include <string>
#include <vector>

// 栈配对的经典解法（题面请在 LeetCode 打开链接阅读；此处只放解法与自测）
bool is_valid(const std::string& s) {
    std::vector<char> st;
    for (char c : s) {
        if (c == '(') st.push_back(')');
        else if (c == '[') st.push_back(']');
        else if (c == '{') st.push_back('}');
        else {
            if (st.empty() || st.back() != c) return false;
            st.pop_back();
        }
    }
    return st.empty();
}

static int checks = 0, failed = 0;
static void eqv(bool got, bool want, const std::string& in, int line) {
    ++checks;
    if (got != want) {
        ++failed;
        std::cout << "[ ASSERT ] 第" << line << "行 输入=" << in
                  << " 期望=" << want << " 实得=" << got << "\n";
    }
}

int main() {
    // 等价类：合法嵌套 / 合法并列 / 类型不匹配 / 顺序颠倒 / 多余左括号 / 多余右括号 / 空串
    eqv(is_valid("()"), true, "()", __LINE__);
    eqv(is_valid("()[]{}"), true, "()[]{}", __LINE__);
    eqv(is_valid("(]"), false, "(]", __LINE__);
    eqv(is_valid("([)]"), false, "([)]", __LINE__);
    eqv(is_valid("("), false, "(", __LINE__);
    eqv(is_valid(")"), false, ")", __LINE__);
    eqv(is_valid(""), true, "", __LINE__);      // 空串属于「合法」等价类，最易漏
    std::cout << "[SUMMARY] 断言=" << checks << " 失败断言=" << failed << "\n";
    return failed ? 1 : 0;
}
